import{_ as p,a as e}from"./chunks/16.1dd179c8.js";import{_ as t,o as r,c as i,O as s}from"./chunks/framework.201d44e9.js";const a="/mobile/debug/1.png",m="/mobile/debug/2.png",n="/mobile/debug/3.png",l="/mobile/debug/4.png",c="/mobile/debug/5.png",d="/mobile/debug/6.png",g="/mobile/debug/7.png",b="/mobile/debug/8.png",_="/mobile/debug/9.png",u="/mobile/debug/10.png",h="/mobile/debug/11.png",P="/mobile/debug/12.png",f="/mobile/debug/14.png",D="/mobile/debug/15.png",B=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"debug/usb-debug.md","filePath":"debug/usb-debug.md","lastUpdated":1751217757000}'),C={name:"debug/usb-debug.md"};function S(v,o,q,k,x,T){return r(),i("div",null,o[0]||(o[0]=[s('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>作为前端开发，我们每天都会用 Chrome DevTools 调试 Chrome 的网页，但其实它还可以远程调试 Android 手机和 IOS 手机的网页。</p><p>那 Chrome DevTools 如何远程调试 Android/IOS 网页呢？它的实现原理是什么？</p><h2 id="远程调试-android-网页" tabindex="-1">远程调试 Android 网页 <a class="header-anchor" href="#远程调试-android-网页" aria-label="Permalink to &quot;远程调试 Android 网页&quot;">​</a></h2><p>用数据线把安卓手机和电脑连接起来，在手机设置里打开 USB 调试：</p><p><img src="'+a+'" alt=""></p><p>然后在 chrome 打开 chrome://inspect 页面，勾选 Discover USB devices（默认是勾选的）：</p><p><img src="'+m+'" alt=""></p><p>这时候下面就会出现一个提示：请在设备上接受 debugging 会话</p><p><img src="'+n+'" alt=""></p><p>在手机上点击确定，就会建立调试会话：</p><p><img src="'+l+'" alt=""></p><p>下面就会列出所有可以调试的网页：</p><p><img src="'+c+'" alt=""></p><p>浏览器里的网页，或者 APP 调试包的 webview 的网页都会列出来。</p><p>点击 inspect 就可以调试了：</p><p>可以审查元素：</p><p><img src="'+d+'" alt=""></p><h2 id="远程调试-ios-网页" tabindex="-1">远程调试 IOS 网页 <a class="header-anchor" href="#远程调试-ios-网页" aria-label="Permalink to &quot;远程调试 IOS 网页&quot;">​</a></h2><p>ios 网页调试只能用 safari 浏览器。</p><p>打开偏好设置 &gt; 高级，勾选显示“开发”菜单：</p><p><img src="'+g+'" alt=""></p><p>之后就会出现“开发”菜单，下面会展示所有连接的设备：</p><p><img src="'+b+'" alt=""></p><p>它会提示你在 iPhone 上启用网页检查器。</p><p>这个是在 设置 &gt; safari 浏览器 &gt; 高级里开启的：</p><p><img src="'+_+'" alt=""></p><p>网页检查器下面也有这么一行提示：</p><p><img src="'+u+'" alt=""></p><p>之后在 Safari 浏览器里打开一个页面，比如 baidu.com：</p><p>在电脑的 Safari 浏览器的开发菜单里就会显示出这个网页：</p><p><img src="'+h+'" alt=""></p><p>不只是 Safari 浏览器，一些 APP 里内嵌的网页开启了调试的话也可以连接。</p><p>之后就可以在电脑上远程调试 iphone 上的网页了：</p><p><img src="'+P+'" alt=""></p><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><p>Chrome DevTools 被设计成了和 Chrome 分离的架构，两者之间通过 WebSocket 通信，设计了专门的通信协议： Chrome DevTools Protocol。</p><p><img src="'+p+'" alt=""></p><p>这样只要实现对接 CDP 协议的 ws 服务端，就可以用 Chrome DevTools 来调试，所以 Chrome DevTools 可以用来调试浏览器的网页、调试 Node.js，调试 Electron 等。</p><p>那自然也就可以远程调试安卓手机的网页了，只要开启了 USB 调试，那手机和电脑就可以做网络通信，从而实现基于 CDP 的调试。</p><p>这个 CDP 的调试协议是 json 格式的，如果想看它传输了什么也是可以的：</p><p>在 Chrome DevTools 的设置里开启 Protocol Monitor：</p><p><img src="'+f+'" alt=""></p><p>然后在 more tools 里打开 Protocol Monitor 面板：</p><p><img src="'+D+'" alt=""></p><p>然后你就可以在 Protocol Monitor 面板里看到所有的 CDP 协议的数据交互了：</p><p><img src="'+e+'" alt=""></p><p>这就是调试的实现原理。</p>',48)]))}const I=t(C,[["render",S]]);export{B as __pageData,I as default};
